// Hook nativo ad alta efficienza per sincronizzazione VSync
static void Hook_VIDEO_WaitVSync(PPCContext* ctx) {
    if (ctx->r[13] >= 0x80000000 && ctx->r[13] < 0x88000000) {
        uint32_t off = (ctx->r[13] + 0x1F0) & (MEM1_SIZE - 1);
        uint32_t val = WII_BYTESWAP32(*reinterpret_cast<uint32_t*>(g_Memory.mem1 + off));
        *reinterpret_cast<uint32_t*>(g_Memory.mem1 + off) = WII_BYTESWAP32(val + 1);
    }
    ctx->r[3] = 1;
    g_Memory.frameReady = true;
    std::this_thread::sleep_for(std::chrono::milliseconds(16));
}

