int StartRecompiledGame() {
    g_Memory.LoadDol("C:/Users/Valerio/Desktop/wiirecomp/boot.dol");
    InitializeGameDispatchTable();
    g_ModEngine.RegisterPreHook(0x80018de0, [](PPCContext* ctx) -> bool {
        Hook_VIDEO_WaitVSync(ctx);
        return true;
    });
    // Diagnostic hooks per bootstrap e init
    g_ModEngine.RegisterPreHook(0x80004020, [](PPCContext* ctx) -> bool {
        Log("[DIAG] 0x80004020 (crt0) entry, LR=0x" + HexStr(ctx->lr) + " SP=0x" + HexStr(ctx->r[1]));
        return false;
    });
    g_ModEngine.RegisterPreHook(0x80005634, [](PPCContext* ctx) -> bool {
        Log("[INIT] Bypass __init_user_runtime (0x80005634) per procedere direttamente all'avvio del gioco");
        return true;
    });
    g_ModEngine.RegisterPreHook(0x80004170, [](PPCContext* ctx) -> bool {
        Log("[INIT] Bypass __init_cpp (0x80004170)");
        return true;
    });
    g_ModEngine.RegisterPreHook(0x8003D780, [](PPCContext* ctx) -> bool {
        Log("[INIT] Bypass __init_array (0x8003D780)");
        return true;
    });
    g_ModEngine.RegisterPreHook(0x8003A084, [](PPCContext* ctx) -> bool {
        Log("[INIT] Bypass __register_frame_info (0x8003A084)");
        return true;
    });
    // Hook __vi_write_i2c (0x8001815C) e __vi_init_encoder (0x8001952C) per evitare blocco hardware I2C
    g_ModEngine.RegisterPreHook(0x8001815C, [](PPCContext* ctx) -> bool {
        return true;
    });
    g_ModEngine.RegisterPreHook(0x8001952C, [](PPCContext* ctx) -> bool {
        return true;
    });

    g_ModEngine.RegisterPreHook(0x800197F8, [](PPCContext* ctx) -> bool {
        Log("[DIAG] 0x800197F8 (VIDEO_Init) entry, LR=0x" + HexStr(ctx->lr));
        return false;
    });
    g_ModEngine.RegisterPreHook(0x800187F4, [](PPCContext* ctx) -> bool {
        Log("[DIAG] 0x800187F4 (CON_InitEx) entry, LR=0x" + HexStr(ctx->lr));
        return false;
    });

    // Hook VIDEO_SetNextFramebuffer (0x80018F5C) per catturare l'indirizzo XFB
    g_ModEngine.RegisterPreHook(0x80018F5C, [](PPCContext* ctx) -> bool {
        uint32_t fb = ctx->r[3];
        g_Memory.currentFramebufferAddress = fb & (MEM1_SIZE - 1);
        g_Memory.frameReady = true;
        if (ctx->r[13] != 0) {
            g_Memory.Write32(0x800BA7B0, fb);
            g_Memory.Write32(ctx->r[13] + 540, 1);
        }
        Log("[VI] VIDEO_SetNextFramebuffer intercettato: fb=0x" + HexStr(fb) + " -> phys 0x" + HexStr(g_Memory.currentFramebufferAddress));
        return true;
    });

    // Hook SYS_GetArena1Lo (0x8001ACF8)
    g_ModEngine.RegisterPreHook(0x8001ACF8, [](PPCContext* ctx) -> bool {
        ctx->r[3] = 0x800E4960;
        return true;
    });

    // Hook SYS_GetArena1Hi (0x8001AD30) per garantire che l'Arena1 nativa sia 128 MB
    g_ModEngine.RegisterPreHook(0x8001AD30, [](PPCContext* ctx) -> bool {
        ctx->r[3] = 0x80000000 + (uint32_t)MEM1_SIZE - 0x1000;
        return true;
    });

    // Hook 0x8001A89C: bypass init sottosistemi hardware libogc (IRQ/LWP/RTC) su Windows
    g_ModEngine.RegisterPreHook(0x8001A89C, [](PPCContext* ctx) -> bool {
        Log("[LIBOGC] Bypass subsys hardware init a 0x8001A89C");
        return true;
    });

    // Hook 0x8001773C: __lwp_heap_allocate - fallback su heap nativo per evitare loop su liste libogc non inizializzate
    static uint32_t s_NativeHeap = 0x80600000;
    g_ModEngine.RegisterPreHook(0x8001773C, [](PPCContext* ctx) -> bool {
        uint32_t size = ctx->r[4];
        uint32_t prev = s_NativeHeap;
        s_NativeHeap = (s_NativeHeap + size + 31) & ~31;
        for (uint32_t i = 0; i < size; ++i) g_Memory.Write8(prev + i, 0);
        ctx->r[3] = prev;
        Log("[LWP_HEAP] Allocati " + std::to_string(size) + " bytes a 0x" + HexStr(prev) + " da LR=0x" + HexStr(ctx->lr));
        return true;
    });

    // Hook __lwp_thread_dispatch (0x80016BF0, 0x80016C78) e Func_0x800255BC per evitare blocco schedulatore LWP
    g_ModEngine.RegisterPreHook(0x80016BF0, [](PPCContext* ctx) -> bool {
        return true;
    });

    g_ModEngine.RegisterPreHook(0x80016C78, [](PPCContext* ctx) -> bool {
        return true;
    });

    g_ModEngine.RegisterPreHook(0x800255BC, [](PPCContext* ctx) -> bool {
        ctx->r[3] = 0;
        return true;
    });

    // Hook WPAD (0x80007630, 0x80007928, 0x800079B8, 0x800079E0, 0x80007904) per evitare blocco controller IOS/Bluetooth
    g_ModEngine.RegisterPreHook(0x80007630, [](PPCContext* ctx) -> bool {
        Log("[WPAD] WPAD_Init bypass: ritorno OK (0)");
        ctx->r[3] = 0;
        return true;
    });

    g_ModEngine.RegisterPreHook(0x80007928, [](PPCContext* ctx) -> bool {
        return true;
    });

    g_ModEngine.RegisterPreHook(0x800079B8, [](PPCContext* ctx) -> bool {
        ctx->r[3] = 0;
        return true;
    });

    g_ModEngine.RegisterPreHook(0x800079E0, [](PPCContext* ctx) -> bool {
        ctx->r[3] = 0;
        return true;
    });

    g_ModEngine.RegisterPreHook(0x80007904, [](PPCContext* ctx) -> bool {
        ctx->r[3] = 0;
        return true;
    });

    // Hook IOS IPC (0x8001C5E0, 0x8001C57C, 0x8001D5EC) per evitare deadlock IPC con Starlet/DI
    g_ModEngine.RegisterPreHook(0x8001C5E0, [](PPCContext* ctx) -> bool {
        ctx->r[3] = 0;
        return true;
    });

    g_ModEngine.RegisterPreHook(0x8001C57C, [](PPCContext* ctx) -> bool {
        return true;
    });

    g_ModEngine.RegisterPreHook(0x8001D5EC, [](PPCContext* ctx) -> bool {
        Log("[IPC] Hook __ipc_init (0x8001D5EC) bypass: simulazione IPC/DI hardware completata");
        ctx->r[3] = 0;
        return true;
    });

    // Hook DSP_Init (0x8001B744) per bypassare loop e interrupt DSP
    g_ModEngine.RegisterPreHook(0x8001B744, [](PPCContext* ctx) -> bool {
        Log("[DSP] Hook DSP_Init (0x8001B744) bypass: DSP pronto");
        ctx->r[3] = 0;
        return true;
    });

    // Hook SYS_Init (0x8001B8FC) per evitare esecuzioni multiple da ctors
    static bool s_SysInitDone = false;
    g_ModEngine.RegisterPreHook(0x8001B8FC, [](PPCContext* ctx) -> bool {
        if (s_SysInitDone) {
            static int s_SysCount = 0;
            if (++s_SysCount <= 5) {
                Log("[SYS] Hook SYS_Init (0x8001B8FC) secondaria evitata: LR=0x" + HexStr(ctx->lr) + " PC=0x" + HexStr(ctx->pc) + " SP=0x" + HexStr(ctx->r[1]));
            }
            return true;
        }
        s_SysInitDone = true;
        Log("[SYS] Hook SYS_Init (0x8001B8FC) prima esecuzione avviata da LR=0x" + HexStr(ctx->lr));
        return false;
    });

    // Hook memalign (0x80032D44) e _memalign_r (0x80030490)
    g_ModEngine.RegisterPreHook(0x80032D44, [](PPCContext* ctx) -> bool {
        uint32_t align = ctx->r[3];
        if (align < 32) align = 32;
        uint32_t size = ctx->r[4];
        s_NativeHeap = (s_NativeHeap + align - 1) & ~(align - 1);
        uint32_t prev = s_NativeHeap;
        s_NativeHeap = (s_NativeHeap + size + 31) & ~31;
        for (uint32_t i = 0; i < size; ++i) g_Memory.Write8(prev + i, 0);
        ctx->r[3] = prev;
        Log("[MEMALIGN] Alloca align=" + std::to_string(align) + " size=" + std::to_string(size) + " -> 0x" + HexStr(prev));
        return true;
    });

    g_ModEngine.RegisterPreHook(0x80030490, [](PPCContext* ctx) -> bool {
        uint32_t align = ctx->r[4];
        if (align < 32) align = 32;
        uint32_t size = ctx->r[5];
        s_NativeHeap = (s_NativeHeap + align - 1) & ~(align - 1);
        uint32_t prev = s_NativeHeap;
        s_NativeHeap = (s_NativeHeap + size + 31) & ~31;
        for (uint32_t i = 0; i < size; ++i) g_Memory.Write8(prev + i, 0);
        ctx->r[3] = prev;
        Log("[_MEMALIGN_R] Alloca align=" + std::to_string(align) + " size=" + std::to_string(size) + " -> 0x" + HexStr(prev));
        return true;
    });

    // Hook free (0x80031604) e _free_r (0x80030588)
    g_ModEngine.RegisterPreHook(0x80031604, [](PPCContext* ctx) -> bool { return true; });
    g_ModEngine.RegisterPreHook(0x80030588, [](PPCContext* ctx) -> bool { return true; });

    // Hook exit (0x800329A4) per uscita ordinata
    g_ModEngine.RegisterPreHook(0x800329A4, [](PPCContext* ctx) -> bool {
        Log("[EXIT] Richiesta uscita ordinata dal gioco.");
        return true;
    });

    // Hook _sbrk_r (0x80020290) - Allocatore nativo heap continuo per malloc/calloc
    g_ModEngine.RegisterPreHook(0x80020290, [](PPCContext* ctx) -> bool {
        int32_t incr = (int32_t)ctx->r[4];
        uint32_t prev = s_NativeHeap;
        if (incr > 0) {
            s_NativeHeap = (s_NativeHeap + incr + 31) & ~31;
        }
        ctx->r[3] = prev;
        Log("[SBRK] Heap alloca: " + std::to_string(incr) + " bytes -> 0x" + HexStr(prev) + " (nuovo break: 0x" + HexStr(s_NativeHeap) + ")");
        return true;
    });

    // Hook abort (0x8002ED58) per diagnostica dettagliata
    g_ModEngine.RegisterPreHook(0x8002ED58, [](PPCContext* ctx) -> bool {
        Log("[CRITICAL] abort() chiamato da LR=0x" + HexStr(ctx->lr));
        std::cerr << "[CRITICAL] abort() chiamato da LR=0x" << std::hex << ctx->lr << "\n";
        return false;
    });

    // Hook calloc (0x8002FF14) e _calloc_r (0x800302D0) per garantire allocazione immediata e sicura
    g_ModEngine.RegisterPreHook(0x8002FF14, [](PPCContext* ctx) -> bool {
        uint32_t num = ctx->r[3];
        uint32_t size = ctx->r[4];
        uint32_t total = num * size;
        uint32_t prev = s_NativeHeap;
        s_NativeHeap = (s_NativeHeap + total + 31) & ~31;
        for (uint32_t i = 0; i < total; ++i) g_Memory.Write8(prev + i, 0);
        ctx->r[3] = prev;
        Log("[CALLOC] Alloca " + std::to_string(num) + " x " + std::to_string(size) + " (" + std::to_string(total) + " bytes) -> 0x" + HexStr(prev));
        return true;
    });

    g_ModEngine.RegisterPreHook(0x800302D0, [](PPCContext* ctx) -> bool {
        uint32_t num = ctx->r[4];
        uint32_t size = ctx->r[5];
        uint32_t total = num * size;
        uint32_t prev = s_NativeHeap;
        s_NativeHeap = (s_NativeHeap + total + 31) & ~31;
        for (uint32_t i = 0; i < total; ++i) g_Memory.Write8(prev + i, 0);
        ctx->r[3] = prev;
        Log("[_CALLOC_R] Alloca " + std::to_string(num) + " x " + std::to_string(size) + " (" + std::to_string(total) + " bytes) -> 0x" + HexStr(prev));
        return true;
    });

    // Hook malloc (0x800315D4) e _malloc_r (0x8003064C)
    g_ModEngine.RegisterPreHook(0x800315D4, [](PPCContext* ctx) -> bool {
        uint32_t size = ctx->r[3];
        uint32_t prev = s_NativeHeap;
        s_NativeHeap = (s_NativeHeap + size + 31) & ~31;
        ctx->r[3] = prev;
        Log("[MALLOC] Alloca " + std::to_string(size) + " bytes -> 0x" + HexStr(prev) + " (nuovo break: 0x" + HexStr(s_NativeHeap) + ")");
        return true;
    });

    g_ModEngine.RegisterPreHook(0x8003064C, [](PPCContext* ctx) -> bool {
        uint32_t size = ctx->r[4];
        uint32_t prev = s_NativeHeap;
        s_NativeHeap = (s_NativeHeap + size + 31) & ~31;
        ctx->r[3] = prev;
        Log("[_MALLOC_R] Alloca " + std::to_string(size) + " bytes -> 0x" + HexStr(prev) + " (nuovo break: 0x" + HexStr(s_NativeHeap) + ")");
        return true;
    });

    // Hook _write_r (0x8003D6C4) per console companion e log
    g_ModEngine.RegisterPreHook(0x8003D6C4, [](PPCContext* ctx) -> bool {
        uint32_t fd = ctx->r[4];
        uint32_t ptr = ctx->r[5];
        uint32_t len = ctx->r[6];
        if ((fd == 1 || fd == 2) && len > 0 && len < 65536) {
            std::string text;
            for (uint32_t i = 0; i < len; ++i) {
                char c = (char)g_Memory.Read8(ptr + i);
                text += c;
            }
            std::cout << text << std::flush;
            Log("[CONSOLE] " + text);
        }
        return false;
    });

    g_ModEngine.RegisterPreHook(0x80005860, [](PPCContext* ctx) -> bool {
        Log("[NATIVE] >>> MAIN (0x80005860) RAGGIUNTO CON SUCCESSO! <<<");
        if (ctx->r[13] != 0) {
            uint32_t newHi = 0x80000000 + (uint32_t)MEM1_SIZE - 0x1000;
            g_Memory.Write32(ctx->r[13] + 584, newHi);
            g_Memory.Write32(ctx->r[13] + 552, newHi);
            Log("[SYS] Arena1Hi configurata a 0x" + HexStr(newHi) + " (128 MB)");
        }
        return false;
    });
    PPCContext& ctx = g_GameContext;
    ctx.Reset();
    ctx.r[1] = 0x817FFF00;
    ctx.r[2] = 0x800410b8;
    ctx.r[13] = 0x8004cce0;
    if (ctx.r[13] != 0) {
        g_Memory.Write32(ctx.r[13] + 132, 0xDEADBEEF);
        g_Memory.Write32(ctx.r[13] + 144, 0x00000001);
        uint32_t newHi = 0x80000000 + (uint32_t)MEM1_SIZE - 0x1000;
        g_Memory.Write32(ctx.r[13] + 584, newHi);
        g_Memory.Write32(ctx.r[13] + 552, newHi);
        g_Memory.Write32(ctx.r[13] + 588, 0x800E4960);
        g_Memory.Write32(ctx.r[13] + 556, 0x800E4960);
        g_Memory.Write32(ctx.r[13] + 580, 0x90002000);
        g_Memory.Write32(ctx.r[13] + 576, 0x933E0000);
    }
    Log("[NATIVE] Esecuzione crt0 / bootstrap / SYS_Init a 0x80004000");
    Func_0x80004000(&ctx);
    if (ctx.r[13] != 0) {
        uint32_t newHi = 0x80000000 + (uint32_t)MEM1_SIZE - 0x1000;
        g_Memory.Write32(ctx.r[13] + 584, newHi);
        g_Memory.Write32(ctx.r[13] + 552, newHi);
    }
    ctx.r[1] = 0x817FFF00;
    ctx.r[2] = 0x800410b8;
    ctx.r[13] = 0x8004cce0;
    Log("[NATIVE] Avvio runtime e main() a 0x80005820");
    Func_0x80005820(&ctx);
    return 0;
}
